class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer,Integer> cnt = new HashMap<>();
        cnt.put(0,1);
        int res = 0;
        int sum = 0;
        for(int i = 0;i<nums.length;i++){
            sum+=nums[i];
            res+=cnt.getOrDefault(sum-k,0);
            cnt.put(sum,cnt.getOrDefault(sum,0)+1);
        }
        return res;
    }
}
